                    config?.export?.billStatus,
                );
            }
            Navigation.goBack(ROUTES.POLICY_ACCOUNTING_XERO_BILL_STATUS_SELECTOR.getRoute(policyID));
        },
        [config?.export?.billStatus, invoiceStatus, policyID],
    );

    return (
        <SelectionScreen
